    assert.equal(row.cycle, (i % 10) + 1);
    assert.equal(row.status, 'pass');
    assert.deepEqual(
      row.actions,
      mode === 'practice'
        ? ['open', 'watch-pause', 'details', 'takeover', 'resume', 'ArrowRight', 'pause', 'back']
        : ['open', 'watch-pause', 'back'],
    );
