      assert.equal(click.diagnosticsSource, 'not-requested');
      assert.equal(click.resources, undefined);
      assert.equal(click.resourceContract, undefined);
      assert(click.visible && click.focused && click.open);
      assert.deepEqual(click.viewport, paused.viewport);
      assert.equal(click.phase, paused.phase);
      assert.equal(click.practice, paused.practice);
      assert.equal(click.painterId, paused.painterId);
      assert.equal(click.lastDraw.paused, true);
      assert.equal(click.lastDraw.quality, paused.lastDraw.quality);
      assert.equal(click.reducedPreference, paused.reducedPreference);
      assert(Number.isFinite(click.lastDraw.width) && click.lastDraw.width > 0);
      for (const value of [paused, click, closed]) {
        assert(Number.isFinite(value.atMs) && value.atMs >= 0);
        assert(Number.isSafeInteger(value.drawCount) && value.drawCount >= 0);
      }
      assert(paused.atMs <= click.atMs && click.atMs <= closed.atMs);
      assert(click.drawCount >= paused.drawCount, 'Draw counter moved backwards before Close');
      unchanged(paused, click);
      unchanged(paused, click, 'ordinary');
      assert.equal(
        click.drawCount,
        closed.drawCount,
        'Demo painted after the trusted Close activation',
      );
    } else {
      assert.equal(paused.drawCount, closed.drawCount);
    }
    assert.equal(paused.lastDraw.paused, true);
    assert.equal(paused.practice, mode === 'practice');
    validQuality(paused);
    const comparison = {
      tier: paused.quality.tier,
      reduced: paused.reducedPreference,
      width: paused.lastDraw.width,
      calibrationSamples: paused.calibration.samples,
    };
    if (comparable.has(mode))
      assert.deepEqual(comparison, comparable.get(mode), 'Comparable Demo cycle changed');
    else comparable.set(mode, comparison);
    if (mode === 'spectator') {
      assert.equal(paused.demo.id, row.opened.id);
      assert(paused.demo.tick >= row.opened.tick);
      assert.equal(row.fork, null);
    } else {
      assert(row.fork && row.fork.demo && row.fork.source);
      assert.equal(row.fork.source.id, row.opened.id);
      assert.equal(row.fork.source.tick, row.fork.demo.tick);
      assert(!runs.has(row.fork.demo.id), 'Practice owner must be fresh');
      runs.add(row.fork.demo.id);
      assert.notEqual(row.fork.demo.id, row.opened.id);
      assert.equal(paused.demo.id, row.fork.demo.id);
      assert(paused.demo.tick > row.fork.demo.tick);
      assert.equal(row.direction, 'right');
    }
  }
  const derived = {
    format: 'SoloQualificationReportV1',
    sourceRevision: source,
    failure: raw.failure,
    snapshots,
  };
  const groups = {};
  let bounds, rows;
  for (const mode of contract.modes)
    for (const boundary of ['paused', 'closed']) {
      const group = `${mode}-${boundary}`;
      const result = assessSoloOwnedResources(derived, {
        group,
        last: 10,
        demo: contract.resources,
      });
      assert.equal(result.bounds.failures, 0, 'Owned resource accounting failed');
      bounds ??= result.bounds;
      rows ??= result.rows;
      groups[group] = result.retention;
    }
